  <body>
    <main class="page">
      <section class="hero" aria-labelledby="support-title">
        <span class="eyebrow">Support</span>
        <h1 id="support-title">Contact our team</h1>
        <p class="subtitle">
          Share your details and we’ll follow up with the right support as soon as possible.
        </p>
      </section>

      <div class="card" id="app"></div>
    </main>

    <script>
      const state = {
        submitted: false,
        values: {
          fullName: "",
          emailAddress: "",
          phoneNumber: "",
        },
      };

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function getErrors(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }

        if (!values.emailAddress.trim()) {
          errors.emailAddress = "Email address is required.";
        } else {
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(values.emailAddress.trim())) {
            errors.emailAddress = "Enter a valid email address.";
          }
        }

        if (values.phoneNumber.trim()) {
          const phonePattern = /^[0-9()+\-\s.]{7,}$/;
          if (!phonePattern.test(values.phoneNumber.trim())) {
            errors.phoneNumber = "Enter a valid phone number.";
          }
        }

        return errors;
      }

      function FormField({ id, label, type, name, value, placeholder, helperText, errorText, required, autocomplete }) {
        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? " *" : ""}</label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              value="${escapeHtml(value)}"
              placeholder="${escapeHtml(placeholder)}"
              ${required ? "required" : ""}
              ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
              aria-describedby="${helperText ? `${id}-help` : ""} ${errorText ? `${id}-error` : ""}".trim()
            />
            ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
            ${errorText ? `<p class="error-text" id="${id}-error" role="alert">${errorText}</p>` : ""}
          </div>
        `;
      }

      function SupportForm() {
        const errors = state.submitted ? getErrors(state.values) : {};
        const hasError = Object.keys(errors).length > 0;

        return `
          <form novalidate>
            ${FormField({
              id: "full-name",
              label: "Full name",
              type: "text",
              name: "fullName",
              value: state.values.fullName,
              placeholder: "Jane Doe",
              errorText: errors.fullName,
              required: true,
              autocomplete: "name",
            })}
            ${FormField({
              id: "email-address",
              label: "Email address",
              type: "email",
              name: "emailAddress",
              value: state.values.emailAddress,
              placeholder: "jane@example.com",
              errorText: errors.emailAddress,
              required: true,
              autocomplete: "email",
            })}
            ${FormField({
              id: "phone-number",
              label: "Phone number",
              type: "tel",
              name: "phoneNumber",
              value: state.values.phoneNumber,
              placeholder: "(555) 123-4567",
              helperText: "Use a phone format you can be reached at, such as (555) 123-4567 or +1 555 123 4567.",
              errorText: errors.phoneNumber,
              required: false,
              autocomplete: "tel",
            })}
            <div class="actions">
              <button type="submit">Send message</button>
            </div>
            ${state.submitted && !hasError ? `<p class="status">Thanks — your message is ready to send.</p>` : ""}
          </form>
        `;
      }

      function render() {
        const app = document.getElementById("app");
        app.innerHTML = SupportForm();

        const form = app.querySelector("form");
        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;

          const formData = new FormData(form);
          state.values.fullName = String(formData.get("fullName") || "");
          state.values.emailAddress = String(formData.get("emailAddress") || "");
          state.values.phoneNumber = String(formData.get("phoneNumber") || "");

          const errors = getErrors(state.values);
          if (!Object.keys(errors).length) {
            app.innerHTML = `
              <form novalidate>
                <p class="status">Thanks — your support request has been captured.</p>
              </form>
            `;
            return;
          }

          render();
        });

        form.querySelectorAll("input").forEach((input) => {
          input.addEventListener("input", (event) => {
            state.values[event.target.name] = event.target.value;
            if (state.submitted) {
              render();
            }
          });
        });
      }

      render();
    </script>
  </body>
