        --shadow: 0 24px 60px rgba(18, 28, 45, 0.12);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(31, 111, 235, 0.12), transparent 30%),
          linear-gradient(180deg, #f7f9fc 0%, var(--bg) 100%);
        color: var(--text);
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .page {
        width: min(100%, 720px);
      }

      .hero {
        margin-bottom: 20px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(31, 111, 235, 0.08);
        color: var(--primary-dark);
        font-size: 0.875rem;
        font-weight: 600;
      }

      h1 {
        margin: 14px 0 8px;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .subtitle {
        margin: 0;
        max-width: 56ch;
        color: var(--muted);
        font-size: 1.02rem;
        line-height: 1.6;
      }

      .card {
        background: rgba(255, 255, 255, 0.88);
        backdrop-filter: blur(12px);
        border: 1px solid rgba(216, 224, 236, 0.9);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: clamp(24px, 4vw, 36px);
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        font-size: 0.95rem;
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: var(--surface);
        color: var(--text);
        padding: 14px 16px;
        font: inherit;
        transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
      }

      input::placeholder {
        color: #8a94a6;
      }

      input:focus {
        outline: none;
        border-color: rgba(31, 111, 235, 0.65);
        box-shadow: 0 0 0 4px rgba(31, 111, 235, 0.12);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.875rem;
        line-height: 1.5;
      }

      .error-text {
        margin: 0;
        color: #c62828;
        font-size: 0.875rem;
        line-height: 1.5;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 6px;
      }

      button {
        appearance: none;
        border: none;
        border-radius: 14px;
        background: linear-gradient(180deg, var(--primary) 0%, var(--primary-dark) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        padding: 14px 20px;
        min-width: 160px;
        cursor: pointer;
        box-shadow: 0 14px 28px rgba(31, 111, 235, 0.22);
        transition: transform 0.15s ease, box-shadow 0.15s ease, filter 0.15s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 32px rgba(31, 111, 235, 0.28);
      }

      button:focus {
        outline: none;
        box-shadow:
          0 0 0 4px rgba(31, 111, 235, 0.18),
          0 18px 32px rgba(31, 111, 235, 0.28);
      }

      .status {
        margin: 0;
        padding: 12px 14px;
        border-radius: 14px;
        background: rgba(31, 111, 235, 0.08);
        color: var(--primary-dark);
        font-weight: 600;
      }

      @media (max-width: 560px) {
        body {
          padding: 20px 12px;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="hero" aria-labelledby="support-title">
        <span class="eyebrow">Support</span>
        <h1 id="support-title">Contact our team</h1>
        <p class="subtitle">
          Share your details and we’ll follow up with the right support as soon as possible.
        </p>
      </section>

      <div class="card" id="app"></div>
    </main>

    <script>
      const state = {
        submitted: false,
        values: {
          fullName: "",
          emailAddress: "",
          phoneNumber: "",
        },
      };

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function getErrors(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }

        if (!values.emailAddress.trim()) {
          errors.emailAddress = "Email address is required.";
        } else {
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(values.emailAddress.trim())) {
            errors.emailAddress = "Enter a valid email address.";
          }
        }

        if (values.phoneNumber.trim()) {
          const phonePattern = /^[0-9()+\-\s.]{7,}$/;
          if (!phonePattern.test(values.phoneNumber.trim())) {
            errors.phoneNumber = "Enter a valid phone number.";
          }
        }

        return errors;
      }

      function FormField({ id, label, type, name, value, placeholder, helperText, errorText, required, autocomplete }) {
        const describedBy = [helperText ? `${id}-help` : null, errorText ? `${id}-error` : null]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? " *" : ""}</label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              value="${escapeHtml(value)}"
              placeholder="${escapeHtml(placeholder)}"
              ${required ? "required" : ""}
              ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            />
            ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
            ${errorText ? `<p class="error-text" id="${id}-error" role="alert">${errorText}</p>` : ""}
          </div>
        `;
      }

      function SupportForm() {
        const errors = state.submitted ? getErrors(state.values) : {};
        const hasError = Object.keys(errors).length > 0;

        return `
          <form novalidate>
            ${FormField({
              id: "full-name",
              label: "Full name",
              type: "text",
              name: "fullName",
              value: state.values.fullName,
              placeholder: "Jane Doe",
              errorText: errors.fullName,
              required: true,
              autocomplete: "name",
            })}
            ${FormField({
              id: "email-address",
              label: "Email address",
              type: "email",
              name: "emailAddress",
              value: state.values.emailAddress,
              placeholder: "jane@example.com",
              errorText: errors.emailAddress,
              required: true,
              autocomplete: "email",
            })}
            ${FormField({
              id: "phone-number",
              label: "Phone number",
              type: "tel",
              name: "phoneNumber",
              value: state.values.phoneNumber,
              placeholder: "(555) 123-4567",
              helperText: "Use a phone format you can be reached at, such as (555) 123-4567 or +1 555 123 4567.",
              errorText: errors.phoneNumber,
              required: false,
              autocomplete: "tel",
            })}
            <div class="actions">
              <button type="submit">Send message</button>
            </div>
            ${state.submitted && !hasError ? `<p class="status">Thanks — your message is ready to send.</p>` : ""}
          </form>
        `;
      }

      function render() {
        const app = document.getElementById("app");
        app.innerHTML = SupportForm();

        const form = app.querySelector("form");
        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;

          const formData = new FormData(form);
          state.values.fullName = String(formData.get("fullName") || "");
          state.values.emailAddress = String(formData.get("emailAddress") || "");
          state.values.phoneNumber = String(formData.get("phoneNumber") || "");

          const errors = getErrors(state.values);
          if (!Object.keys(errors).length) {
            app.innerHTML = `
              <form novalidate>
                <p class="status">Thanks — your support request has been captured.</p>
              </form>
            `;
            return;
          }

          render();
        });

        form.querySelectorAll("input").forEach((input) => {
          input.addEventListener("input", (event) => {
            state.values[event.target.name] = event.target.value;
            if (state.submitted) {
              render();
            }
          });
        });
      }

      render();
    </script>
  </body>
</html>
